"""Build docs/generated/ (openapi.json + api-reference.md) from the FastAPI app.

Usage: gen_docs.py          regenerate in place
       gen_docs.py --check  fail if the committed files are stale or orphaned
"""

import json
import sys
from pathlib import Path

from command_center.app import create_app

OUT_DIR = Path(__file__).resolve().parent.parent / "docs" / "generated"
HTTP_METHODS = ("get", "put", "post", "delete", "patch")


def render() -> dict[str, str]:
    """Return {filename: contents} for every generated file."""
    spec = create_app().openapi()
    lines = [
        "# API reference",
        "",
        "Generated by `mise run gen:build` from the FastAPI app. Do not edit.",
        "",
        "| Method | Path | Summary |",
        "|---|---|---|",
    ]
    for path in sorted(spec["paths"]):
        for method in HTTP_METHODS:
            op = spec["paths"][path].get(method)
            if op is not None:
                lines.append(f"| {method.upper()} | `{path}` | {op.get('summary', '')} |")
    return {
        "openapi.json": json.dumps(spec, indent=2, sort_keys=True) + "\n",
        "api-reference.md": "\n".join(lines) + "\n",
    }


def main(argv: list[str]) -> int:
    """Entry point; returns the process exit code."""
    expected = render()
    if "--check" in argv:
        problems: list[str] = []
        for name, text in expected.items():
            target = OUT_DIR / name
            if not target.exists():
                problems.append(f"missing: {target}")
            elif target.read_bytes() != text.encode():  # bytes: catches CRLF drift
                problems.append(f"stale: {target}")
        if OUT_DIR.exists():
            problems += [
                f"orphaned: {p}" for p in sorted(OUT_DIR.iterdir()) if p.name not in expected
            ]
        if problems:
            print("\n".join(problems), file=sys.stderr)
            print("Run: mise run gen:build", file=sys.stderr)
            return 1
        return 0
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for name, text in expected.items():
        (OUT_DIR / name).write_bytes(text.encode())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
